import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十一章 如何才能解开束缚和捆绑？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/31第三十一章 如何才能解开束缚和捆绑.md","filePath":"meditation/巴利文大藏经/31第三十一章 如何才能解开束缚和捆绑.md"}'),o={name:"meditation/巴利文大藏经/31第三十一章 如何才能解开束缚和捆绑.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第三十一章-如何才能解开束缚和捆绑" tabindex="-1">第三十一章 如何才能解开束缚和捆绑？ <a class="header-anchor" href="#第三十一章-如何才能解开束缚和捆绑" aria-label="Permalink to &quot;第三十一章 如何才能解开束缚和捆绑？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应6经/结缚经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，结缚婆罗门来到佛陀的住所，顶佛陀后，他在一旁坐下，结缚婆罗门对佛陀说：“世尊，世间的人被自己内心生起的念想束缚捆绑，被世间的事物事情束缚捆绑，世尊，谁才能解开这个束缚捆绑，谁才能从自己的念想和世间的事物事情中解脱出来呢？”</p><p>这时，结缚婆罗门说偈言：</p><p>「内外之缠连，人人迷此缠。</p><p>奉问于瞿昙，谁解此缠连。」</p><p>佛陀说：“有智慧的人他们受持戒律，他们由此管束好自己的身体行为，口说言语，内心生起的念想不放逸，不去做恶行，断恶修善，由此他们的内心就能清净安宁下来，智慧也会随之开启。</p><p>精进修行的出家人、修行人，他们就能解开内心念想和世间事物事情对自己的束缚和捆绑。</p><p>那些已经没有贪欲、愤怒、愚痴的人，那些已经明了世间真相和规则，深信因果的人，那些已经除灭一切烦恼和痛苦的阿罗汉圣者，他们已经解开内心念想和世间事物事情的束缚和捆绑，他们不会再挂念和执着世间的事物事情，他们不会再挂念和执着自己的身体、感受、念想、行为、认识分别判断，他们已经从世间的事物事情，自己的身体、感受、念想、行为、认识分别判断中解脱了出来，不会再被它们奴役、折磨、拷打。</p><p>世间的事物事情已经不能让他们产生烦恼和痛苦。他们眼睛看见事物不会生起或挂念喜欢、不喜欢的念想；耳朵听见声音不会生起或挂念喜欢、不喜欢的念想；鼻子闻到气味不会生起或挂念喜欢、不喜欢的念想；舌头尝到味道不会生起或挂念喜欢、不喜欢的念想；对于身体触摸到事物产生的触觉不会生起或挂念喜欢、不喜欢的念想；对于内心想到的思想不会生起或挂念喜欢、不喜欢的念想。</p><p>他们内心不会挂念和执着一切由于遇见世间的事物事情而在他们内心生起的念想，这些念想已经被他们灭除殆尽，他们因为不挂念和执着世间一切的事物事情，他们因为不挂念和执着内心生起的一切念想，所以就不会被世间的一切事物事情束缚捆绑，不会被内心生起的一切念想束缚捆绑。</p><p>由此他们就从世间一切的事物事情，内心的一切念想中解脱了出来，这些束缚和捆绑就被他们完全破坏割断了，他们证悟了解脱的果位，从生死轮回的煎熬和痛苦中永远的解脱出来。”</p><p>这时，佛陀说偈言：</p><p>「智慧人住戒，以修心智慧。</p><p>热心深慎者，彼应离缠连。</p><p>以离于贪著，乃至嗔无明。</p><p>漏尽阿罗汉，解脱于缠连。</p><p>名之以及色，障碍及色想。</p><p>无余尽消灭，此悉断缠连。」</p><p>佛陀说法后，结缚婆罗门欢喜的说到：“世尊，您说的太好了，您解除了我多年的疑惑，请您让我皈依您，做您的在家修行弟子吧，我愿意受持您制定的戒律，我愿意按您的正法去修行。”</p><p>佛陀接受了结缚婆罗门的皈依。</p>',22)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
